INSERT INTO grammar_exercises (id, chapter_id, slug, title, kind, instructions, items, position, is_published)
VALUES (
  'a1000001-0001-4000-8000-000000000232',
  'a1000001-0001-4000-8000-000000000103',
  'ex-3-2-countable-uncountable',
  'Exercise 3.2 - Countable versus Uncountable Error Spotting',
  'correction',
  'Each sentence misuses a noun (usually plural -s or a/an on an uncountable). Rewrite each sentence correctly.',
  $items2$[{"id": "q1", "prompt": "The teacher gave us many useful advices before the exam.", "answer": "The teacher gave us much useful advice before the exam.", "accepted": ["The teacher gave us much useful advice before the exam.", "The teacher gave us a lot of useful advice before the exam."], "reason": "advice is uncountable: no plural; use much/a lot of, not many.", "bn_note": null}, {"id": "q2", "prompt": "I need some informations about the application process.", "answer": "I need some information about the application process.", "accepted": ["I need some information about the application process."], "reason": "information is uncountable.", "bn_note": null}, {"id": "q3", "prompt": "She bought new furnitures for her apartment.", "answer": "She bought new furniture for her apartment.", "accepted": ["She bought new furniture for her apartment."], "reason": "furniture has no plural.", "bn_note": null}, {"id": "q4", "prompt": "The laboratory does not have enough equipments.", "answer": "The laboratory does not have enough equipment.", "accepted": ["The laboratory does not have enough equipment."], "reason": "equipment is uncountable.", "bn_note": null}, {"id": "q5", "prompt": "He has made a good progress in his studies this year.", "answer": "He has made good progress in his studies this year.", "accepted": ["He has made good progress in his studies this year."], "reason": "progress is uncountable: no a.", "bn_note": null}, {"id": "q6", "prompt": "The researchers published several important researches last year.", "answer": "The researchers published several important studies last year.", "accepted": ["The researchers published several important studies last year.", "The researchers published several important pieces of research last year."], "reason": "research is uncountable; countable word is studies.", "bn_note": null}, {"id": "q7", "prompt": "We had a lot of homeworks during the holidays.", "answer": "We had a lot of homework during the holidays.", "accepted": ["We had a lot of homework during the holidays."], "reason": "homework is uncountable.", "bn_note": null}, {"id": "q8", "prompt": "The company installed new softwares on every computer.", "answer": "The company installed new software on every computer.", "accepted": ["The company installed new software on every computer."], "reason": "software is uncountable.", "bn_note": null}, {"id": "q9", "prompt": "There were many traffics on the road this morning.", "answer": "There was heavy traffic on the road this morning.", "accepted": ["There was heavy traffic on the road this morning.", "There was a lot of traffic on the road this morning."], "reason": "traffic is uncountable: no plural; was not were.", "bn_note": null}, {"id": "q10", "prompt": "The hotel provides free accommodations for its staffs.", "answer": "The hotel provides free accommodation for its staff.", "accepted": ["The hotel provides free accommodation for its staff."], "reason": "both accommodation and staff are uncountable here.", "bn_note": null}, {"id": "q11", "prompt": "My knowledges of physics are quite limited.", "answer": "My knowledge of physics is quite limited.", "accepted": ["My knowledge of physics is quite limited."], "reason": "knowledge is uncountable and singular.", "bn_note": null}, {"id": "q12", "prompt": "The government spent a huge money on the project.", "answer": "The government spent a huge amount of money on the project.", "accepted": ["The government spent a huge amount of money on the project.", "The government spent a lot of money on the project."], "reason": "money is uncountable: no direct a; use amount of / a lot of.", "bn_note": null}, {"id": "q13", "prompt": "She gave me two good news yesterday.", "answer": "She gave me two pieces of good news / some good news yesterday.", "accepted": ["She gave me two pieces of good news yesterday.", "She gave me some good news yesterday."], "reason": "news is uncountable despite the final -s.", "bn_note": null}, {"id": "q14", "prompt": "The students carried heavy luggages to the airport.", "answer": "The students carried heavy luggage to the airport.", "accepted": ["The students carried heavy luggage to the airport."], "reason": "luggage is uncountable.", "bn_note": null}, {"id": "q15", "prompt": "The report contains many useful datas about the economy.", "answer": "The report contains much useful data about the economy.", "accepted": ["The report contains much useful data about the economy.", "The report contains a lot of useful data about the economy."], "reason": "data is treated as uncountable/mass; datas is never correct.", "bn_note": null}]$items2$::jsonb,
  2,
  true
)
ON CONFLICT (chapter_id, slug) DO UPDATE SET
